-- TiDB / MySQL Compatible Dump
CREATE DATABASE IF NOT EXISTS `Rpitssr`;
USE `Rpitssr`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `tblsubmissiondetail`;
DROP TABLE IF EXISTS `tblstudentsubmission`;
DROP TABLE IF EXISTS `tblanswer`;
DROP TABLE IF EXISTS `tblquestion`;
DROP TABLE IF EXISTS `tblstudent`;
DROP TABLE IF EXISTS `tbltest`;
DROP TABLE IF EXISTS `tblexamsession`;
DROP TABLE IF EXISTS `tbladmin`;
DROP TABLE IF EXISTS `tblsystemsetting`;
DROP TABLE IF EXISTS `sessions`;
DROP TABLE IF EXISTS `migrations`;
DROP TABLE IF EXISTS `cache_locks`;
DROP TABLE IF EXISTS `cache`;

-- --------------------------------------------------------
-- Table structure and data for `cache`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `cache` (
  `key` varchar(255) NOT NULL,
  `value` mediumtext NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `cache_locks`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `cache_locks` (
  `key` varchar(255) NOT NULL,
  `owner` varchar(255) NOT NULL,
  `expiration` bigint(20) NOT NULL,
  PRIMARY KEY (`key`),
  KEY `cache_locks_expiration_index` (`expiration`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- Table structure and data for `migrations`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `migrations` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `sessions`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `sessions` (
  `id` varchar(255) NOT NULL,
  `user_id` varchar(100) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `payload` longtext NOT NULL,
  `last_activity` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblsystemsetting`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblsystemsetting` (
  `setting_key` varchar(100) NOT NULL,
  `setting_value` longtext DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tbladmin`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tbladmin` (
  `AdminId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `Username` varchar(255) NOT NULL,
  `Password` varchar(255) NOT NULL,
  `Role` varchar(50) NOT NULL DEFAULT 'Admin',
  `Status` varchar(50) NOT NULL DEFAULT 'Active',
  `FirstName` varchar(255) DEFAULT NULL,
  `LastName` varchar(255) DEFAULT NULL,
  `Phone` varchar(50) DEFAULT NULL,
  `ProfileImage` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`AdminId`),
  UNIQUE KEY `tbladmin_username_unique` (`Username`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblexamsession`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblexamsession` (
  `SessionId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `SessionName` varchar(255) NOT NULL,
  `ExamDate` date DEFAULT NULL,
  `Days` varchar(100) DEFAULT NULL,
  `Years` varchar(100) DEFAULT NULL,
  `StartTime` time DEFAULT NULL,
  `EndTime` time DEFAULT NULL,
  `Description` text DEFAULT NULL,
  `Status` enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`SessionId`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tbltest`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tbltest` (
  `TestId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `SessionId` bigint(20) UNSIGNED DEFAULT NULL,
  `ExamDay` varchar(100) DEFAULT NULL,
  `AcademicYear` varchar(100) DEFAULT NULL,
  `CreatedByUserId` bigint(20) UNSIGNED DEFAULT NULL,
  `TestName` varchar(255) NOT NULL,
  `DurationMinutes` int(11) NOT NULL,
  `TotalMarks` int(11) NOT NULL,
  `PassScore` int(11) DEFAULT 50,
  `RandomizeQuestions` tinyint(1) NOT NULL DEFAULT 0,
  `ScheduledAt` timestamp NULL DEFAULT NULL,
  `FinishedAt` timestamp NULL DEFAULT NULL,
  `Status` enum('Draft','Published') NOT NULL DEFAULT 'Draft',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`TestId`),
  KEY `tbltest_sessionid_foreign` (`SessionId`),
  CONSTRAINT `tbltest_sessionid_foreign` FOREIGN KEY (`SessionId`) REFERENCES `tblexamsession` (`SessionId`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblstudent`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblstudent` (
  `StudentId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `StudentCode` varchar(50) DEFAULT NULL,
  `SessionId` bigint(20) UNSIGNED DEFAULT NULL,
  `ExamDay` varchar(100) DEFAULT NULL,
  `AcademicYear` varchar(100) DEFAULT NULL,
  `FirstName` varchar(255) NOT NULL,
  `LastName` varchar(255) NOT NULL,
  `Gender` varchar(255) NOT NULL DEFAULT 'Male',
  `Phone` varchar(255) DEFAULT NULL,
  `ProfileImage` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`StudentId`),
  UNIQUE KEY `tblstudent_studentcode_unique` (`StudentCode`),
  KEY `tblstudent_sessionid_foreign` (`SessionId`),
  CONSTRAINT `tblstudent_sessionid_foreign` FOREIGN KEY (`SessionId`) REFERENCES `tblexamsession` (`SessionId`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblquestion`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblquestion` (
  `QuestionId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `TestId` bigint(20) UNSIGNED NOT NULL,
  `QuestionText` text NOT NULL,
  `Passage` longtext DEFAULT NULL,
  `IsExample` tinyint(1) NOT NULL DEFAULT 0,
  `Points` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`QuestionId`),
  KEY `tblquestion_testid_foreign` (`TestId`),
  CONSTRAINT `tblquestion_testid_foreign` FOREIGN KEY (`TestId`) REFERENCES `tbltest` (`TestId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=411 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblanswer`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblanswer` (
  `AnswerId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `QuestionId` bigint(20) UNSIGNED NOT NULL,
  `AnswerText` text NOT NULL,
  `IsCorrect` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`AnswerId`),
  KEY `tblanswer_questionid_foreign` (`QuestionId`),
  CONSTRAINT `tblanswer_questionid_foreign` FOREIGN KEY (`QuestionId`) REFERENCES `tblquestion` (`QuestionId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1640 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblstudentsubmission`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblstudentsubmission` (
  `SubmissionId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `StudentId` bigint(20) UNSIGNED NOT NULL,
  `TestId` bigint(20) UNSIGNED NOT NULL,
  `StartedAt` timestamp NULL DEFAULT NULL,
  `CompletedAt` timestamp NULL DEFAULT NULL,
  `TotalCorrect` int(11) NOT NULL DEFAULT 0,
  `Score` decimal(8,2) NOT NULL DEFAULT 0.00,
  `Interruptions` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`SubmissionId`),
  KEY `tblstudentsubmission_studentid_foreign` (`StudentId`),
  KEY `tblstudentsubmission_testid_foreign` (`TestId`),
  CONSTRAINT `tblstudentsubmission_studentid_foreign` FOREIGN KEY (`StudentId`) REFERENCES `tblstudent` (`StudentId`) ON DELETE CASCADE,
  CONSTRAINT `tblstudentsubmission_testid_foreign` FOREIGN KEY (`TestId`) REFERENCES `tbltest` (`TestId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure and data for `tblsubmissiondetail`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `tblsubmissiondetail` (
  `DetailId` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `SubmissionId` bigint(20) UNSIGNED NOT NULL,
  `QuestionId` bigint(20) UNSIGNED NOT NULL,
  `SelectedAnswerId` bigint(20) UNSIGNED DEFAULT NULL,
  `IsCorrect` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`DetailId`),
  KEY `tblsubmissiondetail_submissionid_foreign` (`SubmissionId`),
  KEY `tblsubmissiondetail_questionid_foreign` (`QuestionId`),
  KEY `tblsubmissiondetail_selectedanswerid_foreign` (`SelectedAnswerId`),
  CONSTRAINT `tblsubmissiondetail_questionid_foreign` FOREIGN KEY (`QuestionId`) REFERENCES `tblquestion` (`QuestionId`) ON DELETE CASCADE,
  CONSTRAINT `tblsubmissiondetail_selectedanswerid_foreign` FOREIGN KEY (`SelectedAnswerId`) REFERENCES `tblanswer` (`AnswerId`) ON DELETE SET NULL,
  CONSTRAINT `tblsubmissiondetail_submissionid_foreign` FOREIGN KEY (`SubmissionId`) REFERENCES `tblstudentsubmission` (`SubmissionId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
